import { keccak_256 } from "@noble/hashes/sha3.js";
import { ripemd160 } from "@noble/hashes/legacy.js";
import { hexToBytes, bytesToHex, copyToClipboard } from "./utils";
import { bech32 } from "bech32";
import base58 from "bs58";
import { decompressPublicKey, compressPublicKey } from "./ec";

const validateCompressedPubKey = (hex: string): void => {
	// Strip whitespace and 0x prefix
	const cleaned = hex.replace(/^0x/i, "").replace(/\s+/g, "");
	if (!/^[0-9a-fA-F]+$/.test(cleaned)) throw new Error("Invalid hex");
	if (cleaned.length !== 66)
		throw new Error("Compressed pubkey must be 33 bytes (66 hex characters)");
};

const validateUncompressedPubKey = (hex: string): void => {
	// Strip whitespace and 0x prefix
	const cleaned = hex.replace(/^0x/i, "").replace(/\s+/g, "");
	if (!/^[0-9a-fA-F]+$/.test(cleaned)) throw new Error("Invalid hex");
	if (cleaned.length !== 130 || !cleaned.startsWith("04"))
		throw new Error(
			"Uncompressed public key must be 65 bytes (130 hex characters, prefix 04)",
		);
};

const pubToEth = (uncompressed: Uint8Array): string => {
	const hash = keccak_256(uncompressed.slice(1));
	return "0x" + bytesToHex(hash.slice(-20));
};

const pubToTron = async (uncompressed: Uint8Array): Promise<string> => {
	const ethNo0x = bytesToHex(keccak_256(uncompressed.slice(1)).slice(-20));
	const tronBytes = Uint8Array.from([0x41, ...hexToBytes(ethNo0x)]);
	const checksum = await sha256(await sha256(tronBytes));
	const combined = new Uint8Array(tronBytes.length + 4);
	combined.set(tronBytes, 0);
	combined.set(checksum.slice(0, 4), tronBytes.length);
	return base58.encode(combined);
};

const pubToBtcSegWit = async (uncompressed: Uint8Array): Promise<string> => {
	const sha = await sha256(uncompressed);
	const ripe = ripemd160(sha);
	const words = bech32.toWords(ripe);
	return bech32.encode("bc", words);
};

const sha256 = async (data: Uint8Array): Promise<Uint8Array> => {
	const buf = new ArrayBuffer(data.byteLength);
	new Uint8Array(buf).set(data);
	return new Uint8Array(await crypto.subtle.digest("SHA-256", buf));
};

export const initPub2Addr = (): void => {
	const compressedPubKeyInput = document.getElementById(
		"compressed-pubkey-input",
	) as HTMLInputElement;
	const uncompressedPubKeyInput = document.getElementById(
		"uncompressed-pubkey-input",
	) as HTMLInputElement;
	const addrEthInput = document.getElementById("addr-eth-input") as HTMLInputElement;
	const addrTronInput = document.getElementById(
		"addr-tron-input",
	) as HTMLInputElement;
	const addrBtcInput = document.getElementById("addr-btc-input") as HTMLInputElement;
	const errorDiv = document.getElementById("ecdsa-converter-error") as HTMLDivElement;
	const compressedCopyBtn = document.getElementById(
		"compressed-pubkey-copy-btn",
	) as HTMLButtonElement;
	const uncompressedCopyBtn = document.getElementById(
		"uncompressed-pubkey-copy-btn",
	) as HTMLButtonElement;
	const addrEthCopyBtn = document.getElementById(
		"addr-eth-copy-btn",
	) as HTMLButtonElement;
	const addrTronCopyBtn = document.getElementById(
		"addr-tron-copy-btn",
	) as HTMLButtonElement;
	const addrBtcCopyBtn = document.getElementById(
		"addr-btc-copy-btn",
	) as HTMLButtonElement;

	const clearAddresses = (): void => {
		if (addrEthInput) addrEthInput.value = "";
		if (addrTronInput) addrTronInput.value = "";
		if (addrBtcInput) addrBtcInput.value = "";
		if (errorDiv) {
			errorDiv.textContent = "";
			errorDiv.style.display = "none";
		}
	};

	const showError = (message: string): void => {
		if (errorDiv) {
			errorDiv.textContent = message;
			errorDiv.style.display = "block";
		}
	};

	const updateAddresses = async (uncompressed: Uint8Array): Promise<void> => {
		if (addrEthInput) addrEthInput.value = pubToEth(uncompressed);
		if (addrTronInput) addrTronInput.value = await pubToTron(uncompressed);
		if (addrBtcInput) addrBtcInput.value = await pubToBtcSegWit(uncompressed);
	};

	const handleCompressedInput = async (hex: string): Promise<void> => {
		// Normalize input: strip 0x prefix and whitespace
		const cleaned = hex.replace(/^0x/i, "").replace(/\s+/g, "");
		if (compressedPubKeyInput) compressedPubKeyInput.value = cleaned;
		if (uncompressedPubKeyInput) uncompressedPubKeyInput.value = "";
		clearAddresses();

		if (!cleaned) return; // Allow empty input

		try {
			validateCompressedPubKey(cleaned);
			const uncompressed = decompressPublicKey(cleaned);
			if (uncompressedPubKeyInput) uncompressedPubKeyInput.value = uncompressed;
			await updateAddresses(hexToBytes(uncompressed));
		} catch (e) {
			clearAddresses();
			showError((e as Error).message);
		}
	};

	const handleUncompressedInput = async (hex: string): Promise<void> => {
		// Normalize input: strip 0x prefix and whitespace
		const cleaned = hex.replace(/^0x/i, "").replace(/\s+/g, "");
		if (uncompressedPubKeyInput) uncompressedPubKeyInput.value = cleaned;
		if (compressedPubKeyInput) compressedPubKeyInput.value = "";
		clearAddresses();

		if (!cleaned) return; // Allow empty input

		try {
			validateUncompressedPubKey(cleaned);
			const bytes = hexToBytes(cleaned);
			const compressed = compressPublicKey(cleaned);
			if (compressedPubKeyInput) compressedPubKeyInput.value = compressed;
			await updateAddresses(bytes);
		} catch (e) {
			clearAddresses();
			showError((e as Error).message);
		}
	};

	if (compressedPubKeyInput) {
		compressedPubKeyInput.addEventListener("input", (e) => {
			handleCompressedInput((e.target as HTMLInputElement).value);
		});
	}

	if (uncompressedPubKeyInput) {
		uncompressedPubKeyInput.addEventListener("input", (e) => {
			handleUncompressedInput((e.target as HTMLInputElement).value);
		});
	}

	if (compressedCopyBtn && compressedPubKeyInput) {
		compressedCopyBtn.addEventListener("click", () => {
			copyToClipboard(compressedPubKeyInput.value);
		});
	}

	if (uncompressedCopyBtn && uncompressedPubKeyInput) {
		uncompressedCopyBtn.addEventListener("click", () => {
			copyToClipboard(uncompressedPubKeyInput.value);
		});
	}

	if (addrEthCopyBtn && addrEthInput) {
		addrEthCopyBtn.addEventListener("click", () => {
			copyToClipboard(addrEthInput.value);
		});
	}

	if (addrTronCopyBtn && addrTronInput) {
		addrTronCopyBtn.addEventListener("click", () => {
			copyToClipboard(addrTronInput.value);
		});
	}

	if (addrBtcCopyBtn && addrBtcInput) {
		addrBtcCopyBtn.addEventListener("click", () => {
			copyToClipboard(addrBtcInput.value);
		});
	}
};

