import { copyToClipboard } from "./utils";

type Base = "bin" | "oct" | "dec" | "hex";

const validate = (value: string, base: Base): void => {
	if (value === "") {
		return;
	}

	const patterns: Record<Base, RegExp> = {
		bin: /^[01]+$/,
		oct: /^[0-7]+$/,
		dec: /^[0-9]+$/,
		hex: /^[0-9a-fA-F]+$/,
	};

	if (!patterns[base].test(value)) {
		throw new Error("Invalid number");
	}
};

const parseToDecimal = (value: string, base: Base): number => {
	const radixMap: Record<Base, number> = {
		bin: 2,
		oct: 8,
		dec: 10,
		hex: 16,
	};

	const result = parseInt(value, radixMap[base]);

	if (Number.isNaN(result)) {
		throw new Error("Invalid number");
	}

	return result;
};

const formatFromDecimal = (value: number, base: Base): string => {
	const radixMap: Record<Base, number> = {
		bin: 2,
		oct: 8,
		dec: 10,
		hex: 16,
	};

	return value.toString(radixMap[base]);
};

export const initBaseConverter = (): void => {
	const topBaseInput = document.getElementById(
		"top-base-input",
	) as HTMLInputElement;
	const bottomBaseInput = document.getElementById(
		"bottom-base-input",
	) as HTMLInputElement;
	const topBaseSelect = document.getElementById(
		"top-base-select",
	) as HTMLSelectElement;
	const bottomBaseSelect = document.getElementById(
		"bottom-base-select",
	) as HTMLSelectElement;
	const topBaseCopyBtn = document.getElementById(
		"top-base-copy-btn",
	) as HTMLButtonElement;
	const bottomBaseCopyBtn = document.getElementById(
		"bottom-base-copy-btn",
	) as HTMLButtonElement;

	let isUpdating = false; // Prevent infinite loops

	const syncFromTop = (): void => {
		if (isUpdating || !topBaseInput || !bottomBaseInput) return;
		isUpdating = true;

		const value = topBaseInput.value;
		const topBase = topBaseSelect?.value as Base;
		const bottomBase = bottomBaseSelect?.value as Base;

		try {
			validate(value, topBase);
			const decimal = parseToDecimal(value, topBase);
			bottomBaseInput.value = formatFromDecimal(decimal, bottomBase);
			topBaseInput.setAttribute("aria-invalid", "false");
			bottomBaseInput.setAttribute("aria-invalid", "false");
		} catch (e) {
			topBaseInput.setAttribute("aria-invalid", "true");
			bottomBaseInput.value = "";
		} finally {
			isUpdating = false;
		}
	};

	const syncFromBottom = (): void => {
		if (isUpdating || !topBaseInput || !bottomBaseInput) return;
		isUpdating = true;

		const value = bottomBaseInput.value;
		const topBase = topBaseSelect?.value as Base;
		const bottomBase = bottomBaseSelect?.value as Base;

		try {
			validate(value, bottomBase);
			const decimal = parseToDecimal(value, bottomBase);
			topBaseInput.value = formatFromDecimal(decimal, topBase);
			topBaseInput.setAttribute("aria-invalid", "false");
			bottomBaseInput.setAttribute("aria-invalid", "false");
		} catch (e) {
			bottomBaseInput.setAttribute("aria-invalid", "true");
			topBaseInput.value = "";
		} finally {
			isUpdating = false;
		}
	};

	const handleTopBaseChange = (): void => {
		if (!topBaseInput || !bottomBaseInput) return;
		topBaseInput.setAttribute("aria-invalid", "false");
		bottomBaseInput.setAttribute("aria-invalid", "false");
		syncFromTop();
	};

	const handleBottomBaseChange = (): void => {
		if (!topBaseInput || !bottomBaseInput) return;
		topBaseInput.setAttribute("aria-invalid", "false");
		bottomBaseInput.setAttribute("aria-invalid", "false");
		syncFromBottom();
	};

	if (topBaseInput) {
		topBaseInput.addEventListener("input", syncFromTop);
		topBaseInput.setAttribute("aria-invalid", "false");
	}

	if (bottomBaseInput) {
		bottomBaseInput.addEventListener("input", syncFromBottom);
		bottomBaseInput.setAttribute("aria-invalid", "false");
	}

	if (topBaseSelect) {
		topBaseSelect.addEventListener("change", handleTopBaseChange);
	}

	if (bottomBaseSelect) {
		bottomBaseSelect.addEventListener("change", handleBottomBaseChange);
	}

	if (topBaseCopyBtn && topBaseInput) {
		topBaseCopyBtn.addEventListener("click", () => {
			copyToClipboard(topBaseInput.value);
		});
	}

	if (bottomBaseCopyBtn && bottomBaseInput) {
		bottomBaseCopyBtn.addEventListener("click", () => {
			copyToClipboard(bottomBaseInput.value);
		});
	}
};

