// ===== secp256k1 params =====
const P = BigInt(
	"0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEFFFFFC2F",
);
const Gx = BigInt(
	"0x79BE667EF9DCBBAC55A06295CE870B07029BFCDB2DCE28D959F2815B16F81798",
);
const Gy = BigInt(
	"0x483ADA7726A3C4655DA4FBFC0E1108A8FD17B448A68554199C47D08FFB10D4B8",
);

const N = BigInt(
	"0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141",
);

type Point = [bigint, bigint] | null;

// ===== helpers =====
const strip0x = (h: string): string => (h.startsWith("0x") ? h.slice(2) : h);

const mod = (a: bigint, m: bigint): bigint => ((a % m) + m) % m;

const modInv = (a: bigint, m: bigint): bigint => {
	let lm = 1n,
		hm = 0n;
	let low = mod(a, m),
		high = m;

	while (low > 1n) {
		const r = high / low;
		[lm, hm] = [hm - lm * r, lm];
		[low, high] = [high - low * r, low];
	}
	return mod(lm, m);
};

const modPow = (b: bigint, e: bigint, m: bigint): bigint => {
	let r = 1n;
	while (e > 0n) {
		if (e & 1n) r = mod(r * b, m);
		b = mod(b * b, m);
		e >>= 1n;
	}
	return r;
};

// ===== EC math =====
const pointAdd = (P1: Point, P2: Point): Point => {
	if (!P1) return P2;
	if (!P2) return P1;

	const [x1, y1] = P1;
	const [x2, y2] = P2;

	if (x1 === x2 && y1 !== y2) return null;

	const m =
		x1 === x2
			? mod(3n * x1 * x1 * modInv(2n * y1, P), P)
			: mod((y2 - y1) * modInv(x2 - x1, P), P);

	const x3 = mod(m * m - x1 - x2, P);
	const y3 = mod(m * (x1 - x3) - y1, P);
	return [x3, y3];
};

const scalarMult = (k: bigint, point: Point): Point => {
	let res: Point = null;
	let add: Point = point;

	while (k > 0n) {
		if (k & 1n) res = pointAdd(res, add);
		add = pointAdd(add, add);
		k >>= 1n;
	}
	return res;
};

// =======================================================
// 1️⃣ privateKey(0x..) -> compressedPublic(hex)
//    format: prefix(02 or 03) + X(64 hex) = 66 hex chars
// =======================================================
export function privateToPublicCompressed(privHex: string): string {
	const priv = BigInt("0x" + strip0x(privHex));
	const [x, y] = scalarMult(priv, [Gx, Gy])!;
	const prefix = y & 1n ? "03" : "02";

	return prefix + x.toString(16).padStart(64, "0");
}

// =======================================================
// 2️⃣ compressed(0x..) -> uncompressed(hex X||Y)
// =======================================================
export function decompressPublicKey(compHex: string): string {
	const h = strip0x(compHex);
	// Handle both formats: "02"/"03" (standard) or "1"/"0" (legacy)
	let parity: boolean;
	let xStr: string;
	
	if (h.length === 65 && (h[0] === "1" || h[0] === "0")) {
		// Legacy format: "1" or "0" + 64 hex chars
		parity = h[0] === "1";
		xStr = h.slice(1);
	} else if (h.length === 66 && (h.startsWith("02") || h.startsWith("03"))) {
		// Standard format: "02" or "03" + 64 hex chars
		parity = h[0] === "3";
		xStr = h.slice(2);
	} else {
		throw new Error("Invalid compressed public key format");
	}
	
	const x = BigInt("0x" + xStr);

	const y2 = mod(x ** 3n + 7n, P);
	let y = modPow(y2, (P + 1n) / 4n, P);
	if ((y & 1n) !== BigInt(parity)) y = P - y;

	return "04" + x.toString(16).padStart(64, "0") + y.toString(16).padStart(64, "0");
}

// =======================================================
// 3️⃣ uncompressed(0x..) -> compressed(hex)
// =======================================================
export function compressPublicKey(uncompressedHex: string): string {
	const h = strip0x(uncompressedHex);
	let x: bigint;
	let y: bigint;
	
	if (h.startsWith("04")) {
		x = BigInt("0x" + h.slice(2, 66));
		y = BigInt("0x" + h.slice(66));
	} else {
		// If already without prefix, assume it's X||Y format
		x = BigInt("0x" + h.slice(0, 64));
		y = BigInt("0x" + h.slice(64));
	}
	
	const prefix = y & 1n ? "03" : "02";
	return prefix + x.toString(16).padStart(64, "0");
}

export function generatePrivateKey(): string {
	let priv: bigint;

	do {
		const buf = new Uint8Array(32);
		crypto.getRandomValues(buf);

		priv = BigInt(
			"0x" + Array.from(buf, (b) => b.toString(16).padStart(2, "0")).join(""),
		);
	} while (priv === 0n || priv >= N);

	return priv.toString(16).padStart(64, "0");
}

