type ImageFormat = "png" | "jpg" | "webp";

const getFormatFromFileName = (name: string): ImageFormat => {
	const ext = name.split(".").pop()?.toLowerCase();

	if (ext === "jpg" || ext === "jpeg") return "jpg";
	if (ext === "png") return "png";
	if (ext === "webp") return "webp";

	throw new Error("Unsupported format");
};

const loadImage = (src: string): Promise<HTMLImageElement> => {
	return new Promise((resolve, reject) => {
		const img = new Image();
		img.onload = () => resolve(img);
		img.onerror = reject;
		img.src = src;
	});
};

const canvasToBlob = (
	canvas: HTMLCanvasElement,
	format: ImageFormat,
): Promise<Blob> => {
	const mimeMap: Record<ImageFormat, string> = {
		png: "image/png",
		jpg: "image/jpeg",
		webp: "image/webp",
	};

	return new Promise((resolve) => {
		canvas.toBlob((blob) => resolve(blob!), mimeMap[format]);
	});
};

const replaceExtension = (name: string, format: ImageFormat): string => {
	return name.replace(/\.[^.]+$/, `.${format}`);
};

const downloadImage = (blob: Blob, name: string): void => {
	const url = URL.createObjectURL(blob);
	const a = document.createElement("a");
	a.href = url;
	a.download = name;
	a.click();
	URL.revokeObjectURL(url);
};

export const initImageConverter = (): void => {
	const imageFileInput = document.getElementById(
		"image-file-input",
	) as HTMLInputElement;
	const imagePreviewContainer = document.getElementById(
		"image-preview-container",
	) as HTMLDivElement;
	const imageTargetFormat = document.getElementById(
		"image-target-format",
	) as HTMLSelectElement;
	const imageDownloadBtn = document.getElementById(
		"image-download-btn",
	) as HTMLButtonElement;
	const imageConverterCanvas = document.getElementById(
		"image-converter-canvas",
	) as HTMLCanvasElement;

	let currentFile: File | null = null;
	let previewUrl: string | null = null;

	const updatePreview = (url: string | null): void => {
		if (!imagePreviewContainer) return;

		// Clear existing preview
		imagePreviewContainer.innerHTML = "";

		if (url) {
			const img = document.createElement("img");
			img.className = "image-format-converter-preview";
			img.src = url;
			img.alt = "";
			imagePreviewContainer.appendChild(img);
		} else {
			const placeholder = document.createElement("div");
			placeholder.className = "image-format-converter-preview-placeholder";
			imagePreviewContainer.appendChild(placeholder);
		}
	};

	const handleFileChange = (file: File | null): void => {
		// Revoke old preview URL
		if (previewUrl) {
			URL.revokeObjectURL(previewUrl);
			previewUrl = null;
		}

		currentFile = file;

		if (!file) {
			updatePreview(null);
			if (imageTargetFormat) imageTargetFormat.disabled = true;
			if (imageDownloadBtn) imageDownloadBtn.disabled = true;
			return;
		}

		try {
			const format = getFormatFromFileName(file.name);
			if (imageTargetFormat) {
				imageTargetFormat.value = format;
				imageTargetFormat.disabled = false;
			}

			const url = URL.createObjectURL(file);
			previewUrl = url;
			updatePreview(url);

			if (imageDownloadBtn) imageDownloadBtn.disabled = false;
		} catch (error) {
			console.error("Error handling file:", error);
			updatePreview(null);
			if (imageTargetFormat) imageTargetFormat.disabled = true;
			if (imageDownloadBtn) imageDownloadBtn.disabled = true;
		}
	};

	const convertAndDownload = async (): Promise<void> => {
		if (!currentFile || !previewUrl || !imageConverterCanvas) {
			return;
		}

		try {
			const format = imageTargetFormat?.value as ImageFormat;
			const image = await loadImage(previewUrl);
			const ctx = imageConverterCanvas.getContext("2d");

			if (!ctx) {
				throw new Error("Could not get canvas context");
			}

			imageConverterCanvas.width = image.width;
			imageConverterCanvas.height = image.height;

			ctx.clearRect(0, 0, imageConverterCanvas.width, imageConverterCanvas.height);

			// Fill white background for JPG format
			if (format === "jpg") {
				ctx.fillStyle = "#ffffff";
				ctx.fillRect(0, 0, imageConverterCanvas.width, imageConverterCanvas.height);
			}

			ctx.drawImage(image, 0, 0);

			const blob = await canvasToBlob(imageConverterCanvas, format);
			const name = replaceExtension(currentFile.name, format);

			downloadImage(blob, name);
		} catch (error) {
			console.error("Error converting image:", error);
		}
	};

	if (imageFileInput) {
		imageFileInput.addEventListener("change", (e) => {
			const file = (e.target as HTMLInputElement).files?.[0] ?? null;
			handleFileChange(file);
		});
	}

	if (imageDownloadBtn) {
		imageDownloadBtn.addEventListener("click", convertAndDownload);
	}
};

