import { copyToClipboard } from "./utils";

const pad = (n: number): string => n.toString().padStart(2, "0");

const updateDate = (time: number, unixDateOutput: HTMLInputElement): void => {
	const d = new Date(time * 1000);
	const formatted =
		`${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ` +
		`${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
	unixDateOutput.value = formatted;
};

export const initUnixConverter = (): void => {
	const unixTimeInput = document.getElementById(
		"unix-time-input",
	) as HTMLInputElement;
	const unixDateOutput = document.getElementById(
		"unix-date-output",
	) as HTMLInputElement;
	const unixTimeCopyBtn = document.getElementById(
		"unix-time-copy-btn",
	) as HTMLButtonElement;

	if (unixTimeInput && unixDateOutput) {
		// Initialize with current time
		const currentTime = Math.floor(Date.now() / 1000);
		unixTimeInput.value = currentTime.toString();
		updateDate(currentTime, unixDateOutput);

		// Handle input changes
		unixTimeInput.addEventListener("input", (e) => {
			const value = (e.target as HTMLInputElement).value;
			const num = parseInt(value, 10);
			if (!isNaN(num)) {
				updateDate(num, unixDateOutput);
			}
		});
	}

	if (unixTimeCopyBtn && unixTimeInput) {
		unixTimeCopyBtn.addEventListener("click", () => {
			copyToClipboard(unixTimeInput.value);
		});
	}
};

