import { copyToClipboard } from "./utils";

const generateUUID = (): string => {
	return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function(c) {
		const r = (Math.random() * 16) | 0;
		const v = c === "x" ? r : (r & 0x3) | 0x8;
		return v.toString(16);
	});
};

const generateRandomNumber = (): string => {
	// Random number between 0 and 100
	return Math.floor(Math.random() * 101).toString();
};

const generateRandomColor = (): string => {
	const letters = "0123456789ABCDEF";
	let color = "#";
	for (let i = 0; i < 6; i++) {
		color += letters[Math.floor(Math.random() * 16)];
	}
	return color;
};

const updateAllValues = (
	uuidInput: HTMLInputElement,
	numberInput: HTMLInputElement,
	colorInput: HTMLInputElement,
): void => {
	uuidInput.value = generateUUID();
	numberInput.value = generateRandomNumber();
	colorInput.value = generateRandomColor();
};

export const initRandomGenerator = (): void => {
	const uuidInput = document.getElementById("uuid-input") as HTMLInputElement;
	const numberInput = document.getElementById("number-input") as HTMLInputElement;
	const colorInput = document.getElementById("color-input") as HTMLInputElement;
	const regenerateBtn = document.getElementById(
		"regenerate-btn",
	) as HTMLButtonElement;

	if (uuidInput && numberInput && colorInput) {
		updateAllValues(uuidInput, numberInput, colorInput);
	}

	if (regenerateBtn) {
		regenerateBtn.addEventListener("click", () => {
			if (uuidInput && numberInput && colorInput) {
				updateAllValues(uuidInput, numberInput, colorInput);
			}
		});
	}

	document.querySelectorAll(".copy-btn").forEach((button) => {
		button.addEventListener("click", (event) => {
			const targetId = (event.currentTarget as HTMLElement).getAttribute(
				"data-target",
			);
			if (targetId) {
				const input = document.getElementById(targetId) as HTMLInputElement;
				copyToClipboard(input.value);
			}
		});
	});
};

