import { privateToPublicCompressed, generatePrivateKey } from "./ec";
import { copyToClipboard } from "./utils";

const validatePrivKey = (hex: string): void => {
	if (!/^[0-9a-fA-F]+$/.test(hex)) throw new Error("Invalid hex");
	if (hex.length !== 64)
		throw new Error("Private key must be 32 bytes (64 hex)");
};

export const initPriv2Pub = (): void => {
	const privKeyInput = document.getElementById(
		"priv-key-input",
	) as HTMLInputElement;
	const pubKeyInput = document.getElementById(
		"pub-key-input",
	) as HTMLInputElement;
	const errorDiv = document.getElementById(
		"priv-to-pub-error",
	) as HTMLDivElement;
	const randomBtn = document.getElementById(
		"priv-key-random-btn",
	) as HTMLButtonElement;
	const copyBtn = document.getElementById(
		"pub-key-copy-btn",
	) as HTMLButtonElement;

	const showError = (message: string): void => {
		if (errorDiv) {
			errorDiv.textContent = message;
			errorDiv.style.display = "block";
		}
	};

	const clearError = (): void => {
		if (errorDiv) {
			errorDiv.textContent = "";
			errorDiv.style.display = "none";
		}
	};

	const handleInput = (value: string): void => {
		if (privKeyInput) privKeyInput.value = value;
		clearError();

		try {
			validatePrivKey(value);
			const pub = privateToPublicCompressed(value);
			if (pubKeyInput) pubKeyInput.value = pub;
		} catch (e) {
			if (pubKeyInput) pubKeyInput.value = "";
			showError((e as Error).message);
		}
	};

	const generateRandom = (): void => {
		const hex = generatePrivateKey();
		handleInput(hex);
	};

	if (privKeyInput) {
		privKeyInput.addEventListener("input", (e) => {
			handleInput((e.target as HTMLInputElement).value);
		});
	}

	if (randomBtn) {
		randomBtn.addEventListener("click", generateRandom);
	}

	if (copyBtn && pubKeyInput) {
		copyBtn.addEventListener("click", () => {
			copyToClipboard(pubKeyInput.value);
		});
	}
};

