// ---------------- Helpers ----------------

const hexToRgb = (hex: string): [number, number, number] => {
	const r = parseInt(hex.slice(1, 3), 16);
	const g = parseInt(hex.slice(3, 5), 16);
	const b = parseInt(hex.slice(5, 7), 16);
	return [r, g, b];
};

const rgbToHex = (r: number, g: number, b: number): string => {
	return "#" + [r, g, b].map((v) => v.toString(16).padStart(2, "0")).join("");
};

const rgbToHsv = (r: number, g: number, b: number): [number, number, number] => {
	r /= 255;
	g /= 255;
	b /= 255;
	const max = Math.max(r, g, b),
		min = Math.min(r, g, b);
	let h = 0,
		s = 0,
		v = max;
	const d = max - min;
	s = max === 0 ? 0 : d / max;
	if (d !== 0) {
		if (max === r) h = (g - b) / d + (g < b ? 6 : 0);
		else if (max === g) h = (b - r) / d + 2;
		else h = (r - g) / d + 4;
		h *= 60;
	}
	return [Math.round(h), Math.round(s * 100), Math.round(v * 100)];
};

const hsvToRgb = (h: number, s: number, v: number): [number, number, number] => {
	s /= 100;
	v /= 100;
	const c = v * s;
	const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
	const m = v - c;
	let r1 = 0,
		g1 = 0,
		b1 = 0;

	if (0 <= h && h < 60) [r1, g1, b1] = [c, x, 0];
	else if (60 <= h && h < 120) [r1, g1, b1] = [x, c, 0];
	else if (120 <= h && h < 180) [r1, g1, b1] = [0, c, x];
	else if (180 <= h && h < 240) [r1, g1, b1] = [0, x, c];
	else if (240 <= h && h < 300) [r1, g1, b1] = [x, 0, c];
	else [r1, g1, b1] = [c, 0, x];

	return [
		Math.round((r1 + m) * 255),
		Math.round((g1 + m) * 255),
		Math.round((b1 + m) * 255),
	];
};

// ---------------- Validation ----------------

const isValidHex = (value: string): boolean => {
	return /^#([0-9a-fA-F]{0,6})$/.test(value);
};

const isValidRgb = (value: string): boolean => {
	const parts = value.split(",").map((p) => parseInt(p.trim()));
	return (
		parts.length <= 3 && parts.every((p) => (p >= 0 && p <= 255) || isNaN(p))
	);
};

const isValidHsv = (value: string): boolean => {
	const parts = value.split(",").map((p) => parseFloat(p.trim()));
	return parts.length <= 3 && parts.every((p) => !isNaN(p));
};

const generateColor = (): string => {
	const n = Math.floor(Math.random() * 0xffffff);
	return `#${n.toString(16).padStart(6, "0")}`;
};

export const initColorConverter = (): void => {
	const hexInput = document.getElementById("hex-input") as HTMLInputElement;
	const rgbInput = document.getElementById("rgb-input") as HTMLInputElement;
	const hsvInput = document.getElementById("hsv-input") as HTMLInputElement;
	const colorPreview = document.getElementById(
		"color-converter-preview",
	) as HTMLDivElement;

	let isUpdating = false; // Prevent infinite loops

	const handleHexChange = (value: string): void => {
		if (isUpdating) return;
		if (hexInput) hexInput.value = value;

		const valid = isValidHex(value);
		if (hexInput) {
			hexInput.className = valid ? "" : "invalid";
		}

		if (valid && value.length === 7) {
			// Only update when hex is complete
			isUpdating = true;
			const [r, g, b] = hexToRgb(value);
			if (rgbInput) rgbInput.value = `${r},${g},${b}`;
			const [h, s, v] = rgbToHsv(r, g, b);
			if (hsvInput) hsvInput.value = `${h},${s},${v}`;
			if (colorPreview) colorPreview.style.backgroundColor = value;
			isUpdating = false;
		} else if (valid && colorPreview) {
			// Update preview even if incomplete
			colorPreview.style.backgroundColor = value;
		}
	};

	const handleRgbChange = (value: string): void => {
		if (isUpdating) return;
		if (rgbInput) rgbInput.value = value;

		const valid = isValidRgb(value);
		if (rgbInput) {
			rgbInput.className = valid ? "" : "invalid";
		}

		if (valid) {
			const parts = value.split(",").map((p) => parseInt(p.trim()));
			if (parts.length === 3 && parts.every((p) => !isNaN(p) && p >= 0 && p <= 255)) {
				isUpdating = true;
				const [r, g, b] = parts;
				const hex = rgbToHex(r, g, b);
				if (hexInput) hexInput.value = hex;
				const [h, s, v] = rgbToHsv(r, g, b);
				if (hsvInput) hsvInput.value = `${h},${s},${v}`;
				if (colorPreview) colorPreview.style.backgroundColor = hex;
				isUpdating = false;
			}
		}
	};

	const handleHsvChange = (value: string): void => {
		if (isUpdating) return;
		if (hsvInput) hsvInput.value = value;

		const valid = isValidHsv(value);
		if (hsvInput) {
			hsvInput.className = valid ? "" : "invalid";
		}

		if (valid) {
			const parts = value.split(",").map((p) => parseFloat(p.trim()));
			if (parts.length === 3 && parts.every((p) => !isNaN(p))) {
				isUpdating = true;
				const [r, g, b] = hsvToRgb(parts[0], parts[1], parts[2]);
				if (rgbInput) rgbInput.value = `${r},${g},${b}`;
				const hex = rgbToHex(r, g, b);
				if (hexInput) hexInput.value = hex;
				if (colorPreview) colorPreview.style.backgroundColor = hex;
				isUpdating = false;
			}
		}
	};

	// Initialize with a random color
	const initialColor = generateColor();
	handleHexChange(initialColor);

	if (hexInput) {
		hexInput.addEventListener("input", (e) => {
			handleHexChange((e.target as HTMLInputElement).value);
		});
	}

	if (rgbInput) {
		rgbInput.addEventListener("input", (e) => {
			handleRgbChange((e.target as HTMLInputElement).value);
		});
	}

	if (hsvInput) {
		hsvInput.addEventListener("input", (e) => {
			handleHsvChange((e.target as HTMLInputElement).value);
		});
	}
};

