import { copyToClipboard } from "./utils";

type Encoding = "utf8" | "hex" | "base64";

const validateEncoding = (value: string, encoding: Encoding): void => {
	if (value === "") {
		return;
	}

	switch (encoding) {
		case "hex":
			if (!/^[0-9a-fA-F\s]*$/.test(value)) {
				throw new Error("Invalid hex");
			}
			if (value.replace(/\s+/g, "").length % 2 !== 0) {
				throw new Error("Invalid hex length");
			}
			return;

		case "base64":
			if (!/^[A-Za-z0-9+/=\s]*$/.test(value)) {
				throw new Error("Invalid base64");
			}
			atob(value.replace(/\s+/g, ""));
			return;

		case "utf8":
			return;
	}
};

const decodeEncoding = (value: string, encoding: Encoding): Uint8Array => {
	switch (encoding) {
		case "utf8":
			return utf8ToBytes(value);
		case "hex":
			return hexToBytes(value);
		case "base64":
			return base64ToBytes(value);
	}
};

const encodeEncoding = (bytes: Uint8Array, encoding: Encoding): string => {
	switch (encoding) {
		case "utf8":
			return bytesToUtf8(bytes);
		case "hex":
			return bytesToHex(bytes);
		case "base64":
			return bytesToBase64(bytes);
	}
};

const utf8ToBytes = (value: string): Uint8Array => {
	return new TextEncoder().encode(value);
};

const bytesToUtf8 = (bytes: Uint8Array): string => {
	return new TextDecoder().decode(bytes);
};

const bytesToHex = (bytes: Uint8Array): string => {
	return Array.from(bytes)
		.map((b) => b.toString(16).padStart(2, "0"))
		.join("");
};

const hexToBytes = (hex: string): Uint8Array => {
	const normalized = hex.replace(/\s+/g, "");
	if (normalized.length % 2 !== 0) {
		throw new Error("Invalid hex");
	}

	const bytes = new Uint8Array(normalized.length / 2);
	for (let i = 0; i < bytes.length; i++) {
		bytes[i] = parseInt(normalized.slice(i * 2, i * 2 + 2), 16);
	}
	return bytes;
};

const bytesToBase64 = (bytes: Uint8Array): string => {
	let binary = "";
	bytes.forEach((b) => (binary += String.fromCharCode(b)));
	return btoa(binary);
};

const base64ToBytes = (value: string): Uint8Array => {
	const normalized = value.replace(/\s+/g, "");
	const binary = atob(normalized);
	const bytes = new Uint8Array(binary.length);
	for (let i = 0; i < binary.length; i++) {
		bytes[i] = binary.charCodeAt(i);
	}
	return bytes;
};

export const initEncodingConverter = (): void => {
	const leftEncodingTextarea = document.getElementById(
		"left-encoding-textarea",
	) as HTMLTextAreaElement;
	const rightEncodingTextarea = document.getElementById(
		"right-encoding-textarea",
	) as HTMLTextAreaElement;
	const leftEncodingSelect = document.getElementById(
		"left-encoding-select",
	) as HTMLSelectElement;
	const rightEncodingSelect = document.getElementById(
		"right-encoding-select",
	) as HTMLSelectElement;
	const leftEncodingCopyBtn = document.getElementById(
		"left-encoding-copy-btn",
	) as HTMLButtonElement;
	const rightEncodingCopyBtn = document.getElementById(
		"right-encoding-copy-btn",
	) as HTMLButtonElement;

	let isEncodingUpdating = false; // Prevent infinite loops

	const syncFromLeft = (): void => {
		if (isEncodingUpdating || !leftEncodingTextarea || !rightEncodingTextarea) {
			return;
		}
		isEncodingUpdating = true;

		const value = leftEncodingTextarea.value;
		const leftEncoding = leftEncodingSelect?.value as Encoding;
		const rightEncoding = rightEncodingSelect?.value as Encoding;

		try {
			validateEncoding(value, leftEncoding);
			const bytes = decodeEncoding(value, leftEncoding);
			rightEncodingTextarea.value = encodeEncoding(bytes, rightEncoding);
			leftEncodingTextarea.setAttribute("aria-invalid", "false");
			rightEncodingTextarea.setAttribute("aria-invalid", "false");
		} catch (e) {
			leftEncodingTextarea.setAttribute("aria-invalid", "true");
			rightEncodingTextarea.value = "";
		} finally {
			isEncodingUpdating = false;
		}
	};

	const syncFromRight = (): void => {
		if (isEncodingUpdating || !leftEncodingTextarea || !rightEncodingTextarea) {
			return;
		}
		isEncodingUpdating = true;

		const value = rightEncodingTextarea.value;
		const leftEncoding = leftEncodingSelect?.value as Encoding;
		const rightEncoding = rightEncodingSelect?.value as Encoding;

		try {
			validateEncoding(value, rightEncoding);
			const bytes = decodeEncoding(value, rightEncoding);
			leftEncodingTextarea.value = encodeEncoding(bytes, leftEncoding);
			leftEncodingTextarea.setAttribute("aria-invalid", "false");
			rightEncodingTextarea.setAttribute("aria-invalid", "false");
		} catch (e) {
			rightEncodingTextarea.setAttribute("aria-invalid", "true");
			leftEncodingTextarea.value = "";
		} finally {
			isEncodingUpdating = false;
		}
	};

	const handleLeftEncodingChange = (): void => {
		if (!leftEncodingTextarea || !rightEncodingTextarea) return;
		leftEncodingTextarea.setAttribute("aria-invalid", "false");
		rightEncodingTextarea.setAttribute("aria-invalid", "false");
		syncFromLeft();
	};

	const handleRightEncodingChange = (): void => {
		if (!leftEncodingTextarea || !rightEncodingTextarea) return;
		leftEncodingTextarea.setAttribute("aria-invalid", "false");
		rightEncodingTextarea.setAttribute("aria-invalid", "false");
		syncFromRight();
	};

	if (leftEncodingTextarea) {
		leftEncodingTextarea.addEventListener("input", syncFromLeft);
		leftEncodingTextarea.setAttribute("aria-invalid", "false");
	}

	if (rightEncodingTextarea) {
		rightEncodingTextarea.addEventListener("input", syncFromRight);
		rightEncodingTextarea.setAttribute("aria-invalid", "false");
	}

	if (leftEncodingSelect) {
		leftEncodingSelect.addEventListener("change", handleLeftEncodingChange);
	}

	if (rightEncodingSelect) {
		rightEncodingSelect.addEventListener("change", handleRightEncodingChange);
	}

	if (leftEncodingCopyBtn && leftEncodingTextarea) {
		leftEncodingCopyBtn.addEventListener("click", () => {
			copyToClipboard(leftEncodingTextarea.value);
		});
	}

	if (rightEncodingCopyBtn && rightEncodingTextarea) {
		rightEncodingCopyBtn.addEventListener("click", () => {
			copyToClipboard(rightEncodingTextarea.value);
		});
	}
};

