import { copyToClipboard } from "./utils";

const convertFromWei = (weiValue: string, exponent: number): string => {
	try {
		const weiBigInt = BigInt(weiValue);
		const exponentDiff = 18 - exponent;
		const divisor = BigInt(10 ** exponentDiff);
		const result = weiBigInt / divisor;

		if (exponentDiff <= 0) {
			return result.toString();
		}

		const remainder = weiBigInt % divisor;
		if (remainder === 0n) {
			return result.toString();
		}

		const fraction = remainder
			.toString()
			.padStart(exponentDiff, "0")
			.replace(/0+$/, "");
		return fraction ? `${result}.${fraction}` : result.toString();
	} catch {
		return "0";
	}
};

const convertToWei = (value: string, exponent: number): string => {
	try {
		const [integer, fraction = ""] = value.split(".");
		const exponentDiff = 18 - exponent;

		if (exponentDiff <= 0) {
			const integerBigInt = BigInt(integer || "0");
			const multiplier = BigInt(10 ** -exponentDiff);
			return (integerBigInt * multiplier).toString();
		}

		const paddedFraction = fraction
			.padEnd(exponentDiff, "0")
			.slice(0, exponentDiff);
		const integerBigInt = BigInt(integer || "0");
		const fractionBigInt = BigInt(paddedFraction || "0");
		const integerWei = integerBigInt * BigInt(10 ** exponentDiff);

		return (integerWei + fractionBigInt).toString();
	} catch {
		return "0";
	}
};

export const initUnitConverter = (): void => {
	const weiInput = document.getElementById("wei-input") as HTMLInputElement;
	const gweiInput = document.getElementById("gwei-input") as HTMLInputElement;
	const ethInput = document.getElementById("eth-input") as HTMLInputElement;
	const weiCopyBtn = document.getElementById("wei-copy-btn") as HTMLButtonElement;
	const gweiCopyBtn = document.getElementById(
		"gwei-copy-btn",
	) as HTMLButtonElement;
	const ethCopyBtn = document.getElementById("eth-copy-btn") as HTMLButtonElement;

	let weiValue = "1000000000000000000"; // 1 ETH in Wei
	let isUnitUpdating = false; // Prevent infinite loops

	const updateAllUnits = (): void => {
		if (isUnitUpdating || !weiInput || !gweiInput || !ethInput) return;
		isUnitUpdating = true;

		gweiInput.value = convertFromWei(weiValue, 9);
		ethInput.value = convertFromWei(weiValue, 0);

		isUnitUpdating = false;
	};

	const handleWeiChange = (rawValue: string): void => {
		if (isUnitUpdating || !weiInput) return;

		// Wei only accepts integers (no decimals)
		const cleanedValue = rawValue.replace(/[^0-9]/g, "");
		weiInput.value = cleanedValue;
		weiValue = cleanedValue || "0";
		updateAllUnits();
	};

	const handleGweiChange = (rawValue: string): void => {
		if (isUnitUpdating || !gweiInput) return;

		if (rawValue === "" || rawValue === "." || rawValue === "-.") {
			gweiInput.value = rawValue;
			return;
		}

		if (!/^-?\d*\.?\d*$/.test(rawValue)) {
			return;
		}

		if (rawValue.includes(".")) {
			const parts = rawValue.split(".");
			if (parts.length > 2) {
				return;
			}
			// Max 9 decimal places for Gwei (18 - 9 = 9)
			if (parts[1] && parts[1].length > 9) {
				return;
			}
		}

		gweiInput.value = rawValue;
		isUnitUpdating = true;
		weiValue = convertToWei(rawValue, 9);
		weiInput.value = weiValue;
		ethInput.value = convertFromWei(weiValue, 0);
		isUnitUpdating = false;
	};

	const handleEthChange = (rawValue: string): void => {
		if (isUnitUpdating || !ethInput) return;

		if (rawValue === "" || rawValue === "." || rawValue === "-.") {
			ethInput.value = rawValue;
			return;
		}

		if (!/^-?\d*\.?\d*$/.test(rawValue)) {
			return;
		}

		if (rawValue.includes(".")) {
			const parts = rawValue.split(".");
			if (parts.length > 2) {
				return;
			}
			// Max 18 decimal places for Eth (18 - 0 = 18)
			if (parts[1] && parts[1].length > 18) {
				return;
			}
		}

		ethInput.value = rawValue;
		isUnitUpdating = true;
		weiValue = convertToWei(rawValue, 0);
		weiInput.value = weiValue;
		gweiInput.value = convertFromWei(weiValue, 9);
		isUnitUpdating = false;
	};

	if (weiInput) {
		weiInput.value = weiValue;
		weiInput.addEventListener("input", (e) => {
			handleWeiChange((e.target as HTMLInputElement).value);
		});
		updateAllUnits();
	}

	if (gweiInput) {
		gweiInput.addEventListener("input", (e) => {
			handleGweiChange((e.target as HTMLInputElement).value);
		});
	}

	if (ethInput) {
		ethInput.addEventListener("input", (e) => {
			handleEthChange((e.target as HTMLInputElement).value);
		});
	}

	if (weiCopyBtn && weiInput) {
		weiCopyBtn.addEventListener("click", () => {
			copyToClipboard(weiInput.value);
		});
	}

	if (gweiCopyBtn && gweiInput) {
		gweiCopyBtn.addEventListener("click", () => {
			copyToClipboard(gweiInput.value);
		});
	}

	if (ethCopyBtn && ethInput) {
		ethCopyBtn.addEventListener("click", () => {
			copyToClipboard(ethInput.value);
		});
	}
};

